/**
 * Page Object for Logout / Session Management
 * Source: cypress/e2e/orangehrm-logout.cy.js
 * Generated by: /tw-e2e-page-object
 *
 * Selector strategy (third-party app — data-testid cannot be added):
 *   1. cy.contains('element', 'text')         — text-based (moderate, preferred over class names)
 *   2. [class*="userdropdown"]               — partial class match (moderate)
 *   3. input[name]                            — stable HTML attribute
 *   TODO: If OrangeHRM exposes data-testid on user dropdown, use getByTestId().
 */
class LogoutPage {

    // --- Actions ---

    openUserDropdown() {
        // Partial class match — survives minor class renames better than full class
        cy.get('[class*="userdropdown-tab"]').click();
        return this;
    }

    clickLogout() {
        cy.contains('a', 'Logout').click();
        return this;
    }

    logout() {
        this.openUserDropdown();
        this.clickLogout();
        return this;
    }

    // --- Assertions ---

    verifyUserDropdownIsOpen() {
        cy.contains('a', 'Logout').should('be.visible');
        return this;
    }

    verifyDropdownContainsLogout() {
        cy.contains('a', 'Logout').should('be.visible');
        return this;
    }

    verifyLoggedOut() {
        cy.url().should('include', '/auth/login');
        cy.get('input[name="username"]').should('be.visible');
        return this;
    }

    verifyProtectedPageRedirectsToLogin(protectedPath) {
        cy.visit(protectedPath, { failOnStatusCode: false });
        cy.url().should('include', '/auth/login');
        return this;
    }
}

export default new LogoutPage();
